"""Offline renderer showcase. No Ollama, Redis, Temporal or network required.
Run from the project root: python -m examples.render_reference_samples
All business metrics in these demo decks are explicitly illustrative.
"""
from pathlib import Path
from app.services.design import apply_theme
from app.services.render import render_pptx, render_pdf, render_thumbnails


def item(title,body):return {'title':title,'body':body}
def slide(title,layout,items=None,**extra):
    return {'id':title,'title':title,'layout_variant':layout,'items':items or [],'emphasis':' '.join(title.split()[-2:]) if layout!='hero' else '',**extra}


def decks():
    ai=[
        slide('Artificial Intelligence Development','hero',eyebrow='AI Evolution',subtitle='Evolution, current capabilities and the future trajectory in India'),
        slide('Modern AI learns representations from data','numbered',[item('Symbolic AI','Human-written rules encode knowledge and decision logic.'),item('Statistical learning','Models estimate patterns from examples and engineered features.'),item('Foundation models','Large pretrained models support diverse language and multimodal tasks.')],image_key='chip'),
        slide('Developmental eras of artificial intelligence','timeline',timeline=[{'date':'Symbolic era','label':'Rules and search','body':'Expert knowledge defines reasoning steps.'},{'date':'Statistical era','label':'Learning from data','body':'Examples guide model estimation.'},{'date':'Deep learning','label':'Learned representations','body':'Neural networks learn useful features.'},{'date':'Foundation models','label':'General-purpose models','body':'Pretraining supports many downstream tasks.'}]),
        slide('Abstraction depth and hierarchy','steps',[item('Raw input','Text, images and signals enter the model.'),item('Features','Early layers identify reusable local patterns.'),item('Composition','Deeper layers combine features into representations.'),item('Task output','The model generates a task-specific prediction.')]),
        slide('Attention connects context dynamically','cycle',[item('Tokenization','Input becomes a sequence of model tokens.'),item('Attention','Tokens exchange information according to learned relevance.'),item('Transformation','Neural layers refine the contextual representations.'),item('Generation','The model predicts and appends output tokens.')],center_label='Transformer'),
        slide('The AI ecosystem has connected layers','pyramid',[item('Applications and agents','Task-oriented experiences integrate models with tools.'),item('Orchestration and memory','Workflows coordinate retrieval, state and actions.'),item('Foundation models','Pretrained networks process language and other modalities.'),item('Compute infrastructure','Processors, storage and networks support inference and training.')]),
        slide('Multimodal models connect information types','hub',[item('Vision','Images and video provide spatial information.'),item('Language','Text expresses instructions, facts and reasoning.'),item('Audio','Speech and sound provide temporal signals.'),item('Tools','External systems provide actions and calculations.')],center_label='Multimodal AI'),
        slide('Autonomous agents use feedback loops','cycle',[item('Perceive','Observe user requests and the available context.'),item('Plan','Choose the next action and the relevant tool.'),item('Execute','Call a tool within defined permissions.'),item('Verify','Check the result before continuing.')],center_label='Agent loop'),
        slide('Three frontiers shape further development','pillars',[item('Inference and reasoning','More deliberate computation may improve difficult problem solving.'),item('Data quality','Useful training and retrieval data influence model reliability.'),item('Efficient infrastructure','Hardware and serving choices affect latency and cost.')]),
        slide('Safety requires checks throughout delivery','numbered',[item('Evaluation','Test representative tasks and failure cases.'),item('Access controls','Limit actions and data to authorized users.'),item('Monitoring','Review production failures and changing input patterns.'),item('Human oversight','Require review for consequential decisions.')]),
        slide('The next phase connects AI to useful work','numbered',[item('Applied research','Connect model capabilities with real scientific problems.'),item('Enterprise adoption','Integrate reliable assistance into business workflows.'),item('Indian language access','Evaluate coverage across languages and user communities.')],image_key='meeting')]
    sales=[
        slide('Competitive Battlecard Playbook','hero',subtitle='A field guide to positioning, discovery, objection handling and competitive closing'),
        slide('Three pillars support the sales conversation','pillars',[item('Enterprise scalability','Discuss integration, access controls and operational requirements.'),item('Time to value','Define a pilot that tests the buyer’s most important workflow.'),item('Extensible platform','Evaluate whether capabilities can grow with business needs.')]),
        slide('Competitors differ by architectural archetype','comparison',table={'headers':['Dimension','Unified platform','Legacy suite','Point solution'],'rows':[['Scope','Cross-team workflows','Broad modules','Focused task'],['Integration','Shared data model','Configuration dependent','Connector dependent'],['Evaluation','Test across teams','Test deployment effort','Test expansion limits'],['Proof needed','Workflow demonstration','Implementation plan','Integration demonstration']]}),
        slide('Legacy suites require integration discovery','numbered',[item('Services dependency','Ask which implementation activities require external partners.'),item('Acquisition history','Check data boundaries between product modules.'),item('Change velocity','Ask how routine workflow changes reach production.')]),
        slide('Entry pricing needs total-cost analysis','numbered',[item('Department limits','Check whether expansion adds new licenses or tools.'),item('Security requirements','Confirm which controls require a higher pricing tier.'),item('Hidden effort','Include integration and administration in the evaluation.')]),
        slide('Vertical tools can constrain expansion','two_column',[item('Ecosystem fit','Test upstream and downstream integrations.'),item('Vendor roadmap','Ask how change requests enter product planning.'),item('Configuration','Demonstrate a workflow outside the core use case.'),item('Proof required','Request customer evidence for comparable deployments.')]),
        slide('Discovery establishes the evaluation criteria','timeline',timeline=[{'date':'Discovery','label':'Probe friction','body':'Identify the workflow that creates avoidable work.'},{'date':'Assessment','label':'Quantify costs','body':'Estimate cost with buyer-provided evidence.'},{'date':'Validation','label':'Confirm security','body':'Document the required controls.'},{'date':'Selection','label':'Agree proof','body':'Define success before evaluating tools.'}]),
        slide('Objections need relevant evidence','comparison',table={'headers':['Buyer objection','Discovery question','Evidence to provide'],'rows':[['Market reputation','What outcome matters most?','Comparable customer reference'],['Lower competitor price','What is included in the price?','Buyer-specific cost model'],['Specialist capability','Which workflow must work?','Live workflow demonstration'],['Migration concerns','Which dependencies create risk?','Pilot and rollout plan']]}),
        slide('Commercial conversations protect deal value','pillars',[item('Commitment','Connect commercial terms to a clear buyer commitment.'),item('Scope','Discuss scope and service trade-offs explicitly.'),item('Executive alignment','Confirm that the buyer agrees on the business case.')]),
        slide('Deal preparation aligns the team','two_column',[item('Scenario','Practice a buyer conversation with a defined competitor archetype.'),item('Task','Ask discovery questions before presenting a response.'),item('Evidence','Bring the relevant product proof.'),item('Review','Identify unsupported claims and missing buyer context.')]),
        slide('Competitive closing follows a shared plan','timeline',timeline=[{'date':'Discover','label':'Map constraints','body':'Record buyer priorities.'},{'date':'Demonstrate','label':'Prove the workflow','body':'Use buyer-relevant scenarios.'},{'date':'Validate','label':'Confirm value','body':'Review the agreed business case.'},{'date':'Close','label':'Agree next steps','body':'Assign owners and a decision date.'}])]
    pitch=[
        slide('Unified Platform for Scalable Operations','hero',subtitle='Consolidate workflows and give teams a shared operational view'),
        slide('Consolidation creates a measurable value hypothesis','kpi_split',[item('Shared data','Reduce repeated reconciliation between tools.'),item('Workflow coordination','Connect handoffs across teams.'),item('Governance','Apply consistent access controls.')],kpis=[{'value':'3.2x','label':'Illustrative ROI, not a customer result'},{'value':'30%','label':'Illustrative cost reduction hypothesis'},{'value':'4 months','label':'Illustrative payback hypothesis'}]),
        slide('Tool sprawl creates operational friction','numbered',[item('Fragmentation','Teams reconcile inconsistent records across tools.'),item('Manual handoffs','Work stalls when ownership is unclear.'),item('Limited visibility','Leaders lack a common view of execution.')],image_key='workshop'),
        slide('Fragmented architectures increase delivery effort','hub',[item('Data fragmentation','Separate systems create inconsistent operational records.'),item('Process bottlenecks','Manual handoffs increase coordination effort.'),item('Governance gaps','Access policies vary between tools.'),item('License complexity','Overlapping products complicate ownership and budgeting.')],center_label='Operational drag'),
        slide('An integrated platform connects core capabilities','hub',[item('Core data layer','Create a consistent operational data model.'),item('Dashboards','Show shared execution status.'),item('Workflow engine','Coordinate approvals and cross-team work.'),item('Security controls','Manage access and audit activity.')],center_label='Unified platform'),
        slide('Architecture choices affect operational flexibility','comparison',table={'headers':['Dimension','Fragmented tools','Unified platform proposal'],'rows':[['Data model','Tool-specific records','Shared operational model'],['Workflows','Manual coordination','Connected orchestration'],['Administration','Multiple configurations','Common governance approach'],['Evaluation','Connector testing','End-to-end workflow testing']]}),
        slide('A finance pilot tests onboarding improvements','kpi_split',[item('Challenge','Teams coordinate onboarding across separate systems.'),item('Implementation','Pilot a shared checklist and workflow.'),item('Measurement','Compare elapsed time and rework against the baseline.')]),
        slide('A services pilot tests customer handoffs','kpi_split',[item('Challenge','Customer context lives in separate tools.'),item('Implementation','Connect sales and service workflows in a pilot.'),item('Measurement','Track handoff completion and customer response time.')]),
        slide('A technology pilot tests delivery throughput','kpi_split',[item('Challenge','Engineering and support use disconnected queues.'),item('Implementation','Connect issue intake and delivery status.'),item('Measurement','Review cycle time and quality before expansion.')]),
        slide('Structured rollout supports team adoption','timeline',timeline=[{'date':'Discover','label':'Architecture and scope','body':'Map workflows and agree success criteria.'},{'date':'Configure','label':'Data and setup','body':'Connect a bounded set of systems.'},{'date':'Pilot','label':'Team enablement','body':'Train users and monitor early results.'},{'date':'Review','label':'Optimize and expand','body':'Compare results with the agreed baseline.'}]),
        slide('Next steps for a practical evaluation','numbered',[item('Technical audit','Map current systems and integration constraints.'),item('Workflow demonstration','Test the highest-priority business scenario.'),item('Business case','Build a buyer-specific model using verified inputs.')],image_key='meeting')]
    india=[
        slide('India’s Artificial Intelligence Landscape','hero',subtitle='Compute, public digital infrastructure and an expanding talent ecosystem'),
        slide('Four foundations support AI development','pillars',[item('Compute','Reliable infrastructure supports training and inference.'),item('Public infrastructure','Digital platforms create opportunities for useful services.'),item('Innovation','Startups and enterprises explore applied AI solutions.'),item('Skills','Education and training shape practical implementation capacity.')]),
        slide('AI initiatives connect infrastructure and applications','kpi_split',[item('Compute access','Assess infrastructure availability and deployment constraints.'),item('Datasets','Improve quality, access and representation.'),item('Foundation models','Evaluate local language and domain requirements.')]),
        slide('Language inclusion expands citizen access','hub',[item('Speech','Voice interfaces can reduce barriers to interaction.'),item('Translation','Local language access supports broader participation.'),item('Evaluation','Test quality across languages and regional contexts.'),item('Delivery','Design services around user needs and access constraints.')],center_label='Language access'),
        slide('Startups build applications and foundation technology','two_column',[item('Enterprise assistants','Connect models to business knowledge and workflows.'),item('Language technology','Develop and evaluate language-specific capabilities.'),item('Healthcare support','Test assistance within appropriate clinical oversight.'),item('Industrial AI','Apply models to operational and engineering problems.')]),
        slide('Talent development supports practical adoption','steps',[item('Foundations','Build skills in programming, mathematics and data.'),item('Applied learning','Work with real datasets and evaluation tasks.'),item('Engineering','Learn deployment, monitoring and operational practices.'),item('Research','Develop methods and test them rigorously.')]),
        slide('Digital public infrastructure enables AI services','steps',[item('Identity','Design around authorized and appropriate data access.'),item('Transactions','Connect useful services to operational systems.'),item('Governance','Apply privacy, security and accountability controls.'),item('Citizen interface','Evaluate usability and language access.')]),
        slide('India’s next phase depends on useful deployment','kpi_split',[item('Accessible services','Measure practical benefits across user groups.'),item('Enterprise adoption','Validate reliability before expanding deployments.'),item('Responsible operation','Monitor outcomes and support human review.')])]
    return {'dark_lime':ai,'editorial_purple':sales,'corporate_blue':pitch,'india_yellow':india}


def main():
    out=Path('examples/output');out.mkdir(parents=True,exist_ok=True)
    for name,slides in decks().items():
        for i,d in enumerate(slides):d['id']=f's{i+1}'
        theme=apply_theme({}, {'design_theme':name}, '')
        p=out/(name+'.pptx');render_pptx(slides,theme,{},p,{'speaker_notes':True})
        print(p)
        try:
            pdf=render_pdf(p,p.with_suffix('.pdf'))
            render_thumbnails(p,out/name,pdf)
        except RuntimeError as exc:print('PPTX created; optional preview unavailable:',exc)

if __name__=='__main__':main()
